"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["82730"],{3573(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.configuracao_derivacao_fato.regras_com_e_sem_codigo","status":422,"titulo":"As regras de uma deriva\xe7\xe3o contribuem c\xf3digo todas, ou nenhuma no derivado booleano"},"descricao":{"codigo":"uniplus.selecao.configuracao_derivacao_fato.regras_com_e_sem_codigo","requisitos":[],"oQueAconteceu":["Na defini\xe7\xe3o das regras de deriva\xe7\xe3o do processo, uma configura\xe7\xe3o traz regras que contribuem\\num c\xf3digo (`contribui` preenchido) e regras que n\xe3o contribuem. A forma de uma deriva\xe7\xe3o \xe9\\numa s\xf3: no fato categ\xf3rico, todas as regras contribuem um c\xf3digo; no fato booleano, nenhuma\\ncontribui, e a regra ativa torna o fato verdadeiro.","A recusa vem no campo `configuracoes[i].regras` e faz parte da confer\xeancia de forma, que\\nacumula no array `errors[]` todas as viola\xe7\xf5es de todas as configura\xe7\xf5es e regras do pedido\\nantes de consultar o cat\xe1logo de fatos. Quando a forma \xe9 uniforme mas contr\xe1ria ao dom\xednio do\\nfato no cat\xe1logo, a recusa \xe9 outra:\\n[`contribuicao_incoerente_com_o_dominio`](/erros/uniplus.selecao.configuracao_derivacao_fato.contribuicao_incoerente_com_o_dominio).","Esta mesma confer\xeancia tamb\xe9m roda quando o sistema rel\xea a configura\xe7\xe3o congelada da vers\xe3o\\npublicada, na retifica\xe7\xe3o em ato \xfanico. Nesse caso a recusa sai como uma viola\xe7\xe3o \xfanica (sem a lista `errors[]`) e se\\nrefere \xe0 vers\xe3o congelada, n\xe3o ao pedido enviado."],"comoResolver":["Na defini\xe7\xe3o das regras, deixe todas as regras da configura\xe7\xe3o na mesma forma, de acordo com o\\ndom\xednio do fato:","- **Fato categ\xf3rico:** preencha `contribui` em todas as regras.\\n- **Fato booleano:** deixe `contribui` ausente em todas as regras.","Se o erro apareceu na retifica\xe7\xe3o em ato \xfanico, o pedido enviado agora n\xe3o \xe9 a causa: o sistema recusou a\\nconfigura\xe7\xe3o congelada da vers\xe3o publicada, e regravar a configura\xe7\xe3o do processo n\xe3o a\\ncorrige. A causa \xe9 investigada pela equipe t\xe9cnica do Uni+."],"ondeAparece":["Defini\xe7\xe3o de regras de deriva\xe7\xe3o de fatos do processo seletivo","Retifica\xe7\xe3o em ato \xfanico"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Configuracao derivacao fato"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"fd5ea0ff72951399d2b2c1a4f29aeb3ea415db44"}}')}}]);